#!/bin/sh
# SPEC 544.nab_r test: arms capstone-spatial capstone-lifetimes in that order, each in a fresh copy of in/ under /tmp/sr.
# Generated by capstone/ports/spec-cpu2017/board/make-stage.py from runcpu's own command files.
S=$(cd "$(dirname "$0")" && pwd)
V=${SPEC_VEXEC:?set SPEC_VEXEC to the batch launcher}
export CAPSTONE_VM_STATS=1
# perf/ns rq: resume_quantum on and the step budget raised to 10 s for this stage (quantum exits resume inside CV_STEP
# instead of returning to the launcher), both restored at the end
SBP=/sys/module/capstone_vm/parameters/step_budget_ns; sb_old=$(cat $SBP); echo 10000000000 > $SBP; echo "@@B10S step_budget_ns=$(cat $SBP) was $sb_old"
RQP=/sys/module/capstone_vm/parameters/resume_quantum; rq_old=$(cat $RQP); echo 1 > $RQP; echo "@@RQ resume_quantum=$(cat $RQP) was $rq_old"
n=0
bench() { dmesg | grep 'capstone_vm: bench' | tail -1 | sed 's/.*capstone_vm: //'; }
nbench() { dmesg | grep -c 'capstone_vm: bench'; }
up() { cut -d' ' -f1 /proc/uptime; }
# the module's cumulative in-context counters (sysfs, 0444): their delta over a command sums every context it ran
sysb() { for f in cycles instret entries; do cat /sys/module/capstone_vm/parameters/bench_$f 2>/dev/null || echo 0; done | tr '\n' ' '; }
echo "@@SPEC-STAGE 544.nab_r test arms=capstone-spatial,capstone-lifetimes commands=1 validations=0"
echo "@@SPEC-ARM-BEGIN capstone-spatial"
cd / && rm -rf /tmp/sr && mkdir -p /tmp/sr && cp -a "$S/in/." /tmp/sr/ && cd /tmp/sr || exit 1
echo "@@SPEC-BEGIN $n run capstone-spatial 0"
s0=$(sysb)
u0=$(up)
"$V" "$S/bin/capstone-spatial/nab_r_base.capstone-spatial" hkrdenq 1930344093 1000 > hkrdenq.out 2>> hkrdenq.err
rc=$?
u1=$(up)
s1=$(sysb)
sys=$(echo $s0 $s1 | awk '{printf "%.0f,%.0f,%.0f", $4-$1, $5-$2, $6-$3}')
echo "@@SPEC-END $n run capstone-spatial 0 rc=$rc up0=$u0 up1=$u1 sys=$sys nbench=$(nbench) $(grep -a CAPSTONE_VM_STATS hkrdenq.err 2>/dev/null | tail -1) :: $(bench)"
n=$((n+1))
echo "@@SPEC-HASH-BEGIN capstone-spatial"
find . -type f | sort | while read -r f; do sha256sum "$f"; done
echo "@@SPEC-HASH-END capstone-spatial"
if [ -f hkrdenq.err ] && [ $(wc -c < hkrdenq.err) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-spatial hkrdenq.err"; gzip -9c hkrdenq.err | base64; echo "@@SPEC-FILE-END"; fi
if [ -f hkrdenq.out ] && [ $(wc -c < hkrdenq.out) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-spatial hkrdenq.out"; gzip -9c hkrdenq.out | base64; echo "@@SPEC-FILE-END"; fi
echo "@@SPEC-ARM-END capstone-spatial"
echo "@@SPEC-ARM-BEGIN capstone-lifetimes"
cd / && rm -rf /tmp/sr && mkdir -p /tmp/sr && cp -a "$S/in/." /tmp/sr/ && cd /tmp/sr || exit 1
echo "@@SPEC-BEGIN $n run capstone-lifetimes 0"
s0=$(sysb)
u0=$(up)
"$V" "$S/bin/capstone-lifetimes/nab_r_base.capstone-lifetimes" hkrdenq 1930344093 1000 > hkrdenq.out 2>> hkrdenq.err
rc=$?
u1=$(up)
s1=$(sysb)
sys=$(echo $s0 $s1 | awk '{printf "%.0f,%.0f,%.0f", $4-$1, $5-$2, $6-$3}')
echo "@@SPEC-END $n run capstone-lifetimes 0 rc=$rc up0=$u0 up1=$u1 sys=$sys nbench=$(nbench) $(grep -a CAPSTONE_VM_STATS hkrdenq.err 2>/dev/null | tail -1) :: $(bench)"
n=$((n+1))
echo "@@SPEC-HASH-BEGIN capstone-lifetimes"
find . -type f | sort | while read -r f; do sha256sum "$f"; done
echo "@@SPEC-HASH-END capstone-lifetimes"
if [ -f hkrdenq.err ] && [ $(wc -c < hkrdenq.err) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-lifetimes hkrdenq.err"; gzip -9c hkrdenq.err | base64; echo "@@SPEC-FILE-END"; fi
if [ -f hkrdenq.out ] && [ $(wc -c < hkrdenq.out) -le ${SPEC_INBAND_MAX:-65536} ]; then echo "@@SPEC-FILE capstone-lifetimes hkrdenq.out"; gzip -9c hkrdenq.out | base64; echo "@@SPEC-FILE-END"; fi
echo "@@SPEC-ARM-END capstone-lifetimes"
cd / && rm -rf /tmp/sr /tmp/sw
echo $sb_old > $SBP; echo "@@B10S restored step_budget_ns=$(cat $SBP)"
echo $rq_old > $RQP; echo "@@RQ restored resume_quantum=$(cat $RQP)"
echo "@@SPEC-DONE 544.nab_r test"
